/* Courbe prix/yield d'une obligation avec tangente de duration */
(function () {
  var svg = document.getElementById("dy-chart");
  if (!svg) return;
  var m = 2; // semestriel
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function price(c, Ty, yPct){
    var n=Math.round(Ty*m), cpn=c/m, yd=yPct/100, p=0;
    for (var i=1;i<=n;i++){ var cf=cpn+(i===n?100:0); p+=cf/Math.pow(1+yd/m,i); }
    return p;
  }
  function metrics(c, Ty, yPct){
    var n=Math.round(Ty*m), cpn=c/m, yd=yPct/100, p=0, macw=0;
    for (var i=1;i<=n;i++){ var cf=cpn+(i===n?100:0); var pv=cf/Math.pow(1+yd/m,i); p+=pv; macw+=(i/m)*pv; }
    var mac=macw/p, mod=mac/(1+yd/m);
    var d=1e-4;
    var conv=(price(c,Ty,(yd+d)*100)+price(c,Ty,(yd-d)*100)-2*p)/(p*d*d);
    return {price:p, mac:mac, mod:mod, conv:conv};
  }

  function draw(){
    var c=v("dy-c"), Ty=v("dy-t"), y=v("dy-y");
    setT("dy-c-o", c.toFixed(1)+"%"); setT("dy-t-o", Ty.toFixed(0)); setT("dy-y-o", y.toFixed(1)+"%");
    var mt=metrics(c,Ty,y);
    setT("dy-price", mt.price.toFixed(2));
    var yrs = al()==="en"?" y":(al()==="nl"?" j":" ans");
    setT("dy-mac", mt.mac.toFixed(2)+yrs);
    setT("dy-mod", mt.mod.toFixed(2));
    setT("dy-conv", mt.conv.toFixed(2));

    var W=520,H=300,L=52,R0=16,T0=16,B=34, pw=W-L-R0, ph=H-T0-B;
    var ylo=Math.max(0.5, y-4), yhi=y+4;
    var ps=[]; for (var yy=ylo; yy<=yhi+1e-9; yy+=0.1) ps.push(price(c,Ty,yy));
    var pmin=Math.min.apply(null,ps), pmax=Math.max.apply(null,ps);
    var pad=(pmax-pmin)*0.12||1; pmin-=pad; pmax+=pad;
    function px(yy){ return L + (yy-ylo)/(yhi-ylo)*pw; }
    function py(val){ return T0 + (1-(val-pmin)/(pmax-pmin))*ph; }

    var g="";
    // tangente de duration : B(y) + dB/dy*(yy-y), dB/dy = -mod*B (par unité de yield décimal)
    var B0=mt.price, slope=-mt.mod*B0/100; // par point de %
    var tanY1=B0+slope*(ylo-y), tanY2=B0+slope*(yhi-y);
    g+='<line x1="'+px(ylo).toFixed(1)+'" y1="'+py(tanY1).toFixed(1)+'" x2="'+px(yhi).toFixed(1)+'" y2="'+py(tanY2).toFixed(1)+'" stroke="var(--gold)" stroke-width="1.8" stroke-dasharray="6 4"/>';
    // courbe prix/yield
    var d="";
    for (var i=0;i<=140;i++){ var yy=ylo+(yhi-ylo)*i/140; d+=(i===0?"M ":" L ")+px(yy).toFixed(1)+","+py(price(c,Ty,yy)).toFixed(1); }
    g+='<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    // point de tangence
    g+='<circle cx="'+px(y).toFixed(1)+'" cy="'+py(B0).toFixed(1)+'" r="4.5" fill="var(--teal)"/>';
    g+='<line x1="'+px(y).toFixed(1)+'" y1="'+py(B0).toFixed(1)+'" x2="'+px(y).toFixed(1)+'" y2="'+(T0+ph).toFixed(1)+'" stroke="var(--ink-mute)" stroke-width="0.8" stroke-dasharray="2 3"/>';
    // axes
    g+='<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+T0+'" x2="'+L+'" y2="'+(T0+ph)+'"/>';
    var xl = al()==="en"?"yield (%)":(al()==="nl"?"yield (%)":"yield (%)");
    var yl = al()==="en"?"price":(al()==="nl"?"prijs":"prix");
    g+='<text class="lab" x="'+(L+pw)+'" y="'+(T0+ph+16)+'" text-anchor="end">'+xl+'</text>';
    g+='<text class="lab" x="'+L+'" y="'+(T0-4)+'" text-anchor="start">'+yl+'</text>';
    var xt0=Math.ceil(ylo); for (var t=xt0;t<=yhi;t+=2){ g+='<text class="tick" x="'+px(t).toFixed(1)+'" y="'+(T0+ph+14)+'" text-anchor="middle">'+t+'</text>'; }
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(B0)+3).toFixed(1)+'" text-anchor="end">'+B0.toFixed(0)+'</text>';
    // légende
    var lg = al()==="en"?"tangent = duration":(al()==="nl"?"tangens = duration":"tangente = duration");
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(T0+12)+'" text-anchor="end" fill="var(--gold)">'+lg+'</text>';
    svg.innerHTML=g;
  }
  ["dy-c","dy-t","dy-y"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
